CREATE OR REPLACE FUNCTION public.cal_admit_run(p_quote_id uuid, p_page_id uuid, p_client_request_id text, p_action text, p_round integer, p_strategy text, p_image_revision text, p_payload_hash text, p_round_token text DEFAULT NULL::text, p_points integer DEFAULT 1)
 RETURNS TABLE(ok boolean, status text, run_id uuid, error_code text, response_payload jsonb, points_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_company uuid;
  v_quote RECORD;
  v_page RECORD;
  v_flag boolean;
  v_existing RECORD;
  v_quota RECORD;
  v_run_id uuid;
BEGIN
  IF v_user IS NULL THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'unauthenticated', NULL::jsonb, NULL::integer;
    RETURN;
  END IF;

  IF p_client_request_id IS NULL OR length(trim(p_client_request_id)) < 8
     OR length(p_client_request_id) > 128 THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'bad_request', NULL::jsonb, NULL::integer;
    RETURN;
  END IF;

  IF p_payload_hash IS NULL OR length(p_payload_hash) < 8
     OR p_image_revision IS NULL OR length(p_image_revision) = 0 THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'bad_request', NULL::jsonb, NULL::integer;
    RETURN;
  END IF;

  -- Round/strategy contract (server is the authority; route pre-validates
  -- the HMAC signature itself because the secret never reaches SQL).
  -- Round 0 permits ONLY the initial search; refine requires round 1.
  IF NOT (
       (p_round = 0 AND p_action = 'search' AND p_strategy = 'initial')
    OR (p_round = 1 AND p_action = 'search' AND p_strategy = 'different_references')
    OR (p_round = 1 AND p_action = 'refine' AND p_strategy = 'refine_reference')
  ) THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'invalid_round', NULL::jsonb, NULL::integer;
    RETURN;
  END IF;
  IF p_round = 1 AND (p_round_token IS NULL OR length(trim(p_round_token)) = 0) THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'invalid_round', NULL::jsonb, NULL::integer;
    RETURN;
  END IF;

  -- Company context from the caller's profile (never client-supplied).
  SELECT u.company_id INTO v_company FROM public.users u WHERE u.id = v_user;
  IF v_company IS NULL THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'no_company', NULL::jsonb, NULL::integer;
    RETURN;
  END IF;

  -- Ownership chain, then LOCK THE PAGE ROW: admission for one page is
  -- serialized exactly like sa_admit_run serializes on the conversation row.
  SELECT * INTO v_quote FROM public.quotes q
   WHERE q.id = p_quote_id AND q.company_id = v_company;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'quote_not_found', NULL::jsonb, NULL::integer;
    RETURN;
  END IF;

  SELECT * INTO v_page FROM public.takeoff_pages tp
   WHERE tp.id = p_page_id AND tp.quote_id = p_quote_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'page_not_found', NULL::jsonb, NULL::integer;
    RETURN;
  END IF;

  -- Dark-launch flag.
  SELECT public.calibration_ai_enabled(v_company) INTO v_flag;
  IF NOT COALESCE(v_flag, false) THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'flag_off', NULL::jsonb, NULL::integer;
    RETURN;
  END IF;

  -- Dedup BEFORE quota (MEMORY invariant): resolve prior attempts first.
  SELECT * INTO v_existing FROM public.calibration_runs r
   WHERE r.company_id = v_company AND r.client_request_id = p_client_request_id;

  IF FOUND THEN
    IF v_existing.payload_hash <> p_payload_hash THEN
      RETURN QUERY SELECT false, 'refused', NULL::uuid, 'request_id_conflict', NULL::jsonb, NULL::integer;
      RETURN;
    END IF;

    -- Stale-run recovery: an admitted/running row older than 10 minutes
    -- (route maxDuration is 5) means a crashed worker. Refund + terminalize
    -- so the client can retry cleanly with a NEW request id.
    IF v_existing.status IN ('admitted','running')
       AND v_existing.created_at < now() - interval '10 minutes' THEN
      UPDATE public.companies c
         SET ai_assist_points_used = GREATEST(c.ai_assist_points_used - v_existing.points_charged, 0)
       WHERE c.id = v_existing.company_id;
      UPDATE public.calibration_runs r
         SET status = 'failed_refunded', error_code = 'stale_run_recovered', finished_at = now()
       WHERE r.id = v_existing.id AND r.status IN ('admitted','running');
      RETURN QUERY SELECT true, 'duplicate_failed', v_existing.id, 'stale_run_recovered', NULL::jsonb, NULL::integer;
      RETURN;
    END IF;

    IF v_existing.status = 'succeeded' THEN
      RETURN QUERY SELECT true, 'replay', v_existing.id, NULL::text, v_existing.response_payload, NULL::integer;
      RETURN;
    END IF;
    IF v_existing.status = 'failed_refunded' THEN
      RETURN QUERY SELECT true, 'duplicate_failed', v_existing.id, v_existing.error_code, NULL::jsonb, NULL::integer;
      RETURN;
    END IF;
    RETURN QUERY SELECT true, 'in_flight', v_existing.id, NULL::text, NULL::jsonb, NULL::integer;
    RETURN;
  END IF;

  -- Stateful single-use round budget: at most ONE round-1 attempt (any
  -- outcome) per page + image revision. The HMAC token alone can no longer
  -- authorise a replayed second round.
  IF p_round = 1 AND EXISTS (
    SELECT 1 FROM public.calibration_runs r
     WHERE r.page_id = p_page_id
       AND r.image_revision = p_image_revision
       AND r.round = 1
  ) THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'round_budget_consumed', NULL::jsonb, NULL::integer;
    RETURN;
  END IF;

  -- Quota reservation + charge, INSIDE this transaction, AFTER all refusal
  -- paths above (dedup-before-quota). p_points defaults to the canonical
  -- CALIBRATION_SEARCH_POINT_COST (1) kept in app/lib/takeoff/pointCost.ts.
  -- Defensive subtransaction: check_and_deduct_ai_points has a LATENT type
  -- bug for NULL-limit plans (untyped NULL in its point_limit column makes
  -- the whole function raise 42804 instead of returning allowed=false).
  -- That RPC is shared billing infrastructure and is NOT modified here; a
  -- failure from it must refuse admission cleanly, never crash the ledger.
  BEGIN
    SELECT * INTO v_quota FROM public.check_and_deduct_ai_points(v_company, GREATEST(COALESCE(p_points, 1), 1));
  EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'insufficient_points', NULL::jsonb, 0;
    RETURN;
  END;
  IF NOT v_quota.allowed THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, 'insufficient_points', NULL::jsonb, COALESCE(v_quota.remaining, 0);
    RETURN;
  END IF;

  INSERT INTO public.calibration_runs (
    company_id, user_id, quote_id, page_id, client_request_id,
    image_revision, action, round, strategy, payload_hash, round_token,
    status, points_charged
  ) VALUES (
    v_company, v_user, p_quote_id, p_page_id, p_client_request_id,
    p_image_revision, p_action, p_round, p_strategy, p_payload_hash, p_round_token,
    'admitted', GREATEST(COALESCE(p_points, 1), 1)
  )
  RETURNING id INTO v_run_id;

  RETURN QUERY SELECT true, 'accepted', v_run_id, NULL::text, NULL::jsonb, v_quota.remaining;
END;
$function$

CREATE OR REPLACE FUNCTION public.cal_finish_run(p_run_id uuid, p_status text, p_response jsonb DEFAULT NULL::jsonb, p_error_code text DEFAULT NULL::text)
 RETURNS TABLE(ok boolean, refunded boolean, points_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_run RECORD;
  v_status RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN QUERY SELECT false, false, NULL::integer;
    RETURN;
  END IF;

  SELECT * INTO v_run FROM public.calibration_runs r
   WHERE r.id = p_run_id AND r.user_id = auth.uid()
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, false, NULL::integer;
    RETURN;
  END IF;

  -- Idempotency guard: terminal runs are immutable.
  IF v_run.status IN ('succeeded','failed_refunded') THEN
    RETURN QUERY SELECT true, false, NULL::integer;
    RETURN;
  END IF;

  IF p_status NOT IN ('succeeded','failed_refunded') THEN
    RAISE EXCEPTION 'invalid terminal status: %', p_status;
  END IF;

  IF p_status = 'failed_refunded' THEN
    -- Atomic refund: one statement, concurrency-safe, never negative.
    UPDATE public.companies c
       SET ai_assist_points_used = GREATEST(c.ai_assist_points_used - v_run.points_charged, 0)
     WHERE c.id = v_run.company_id;
  END IF;

  UPDATE public.calibration_runs r
     SET status = p_status,
         response_payload = p_response,
         error_code = p_error_code,
         finished_at = now()
   WHERE r.id = p_run_id;

  SELECT * INTO v_status FROM public.get_ai_assist_points_status(v_run.company_id);

  RETURN QUERY SELECT true, (p_status = 'failed_refunded'), v_status.remaining;
END;
$function$

CREATE OR REPLACE FUNCTION public.cal_verify_refine_parent(p_run_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_run RECORD;
  v_company uuid;
BEGIN
  IF v_user IS NULL THEN
    RETURN false;
  END IF;

  SELECT * INTO v_run FROM public.calibration_runs r
   WHERE r.id = p_run_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  -- Company membership from the caller's profile (never client-supplied).
  SELECT u.company_id INTO v_company FROM public.users u WHERE u.id = v_user;
  IF v_company IS NULL OR v_run.company_id <> v_company THEN
    RETURN false;
  END IF;

  -- Only a SUCCEEDED run can parent a targeted refine: its response payload
  -- was persisted and its candidates were actually shown to the user.
  RETURN v_run.status = 'succeeded';
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_quote_status_usage_delta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_period date := date_trunc('month', (now() AT TIME ZONE 'UTC'))::date;
  v_company_exists boolean;
BEGIN
  -- Only fire on status changes where OLD was 'draft' and NEW is not 'draft'.
  -- This is the "first real save" - draft becomes confirmed/sent/etc.
  IF (TG_OP = 'UPDATE') THEN
    IF OLD.status = 'draft' AND NEW.status <> 'draft' THEN
      INSERT INTO public.company_quote_usage (company_id, period_start, quotes_created)
      VALUES (NEW.company_id, v_period, 1)
      ON CONFLICT (company_id, period_start)
        DO UPDATE SET quotes_created = company_quote_usage.quotes_created + 1;
    ELSIF OLD.status <> 'draft' AND NEW.status = 'draft' THEN
      -- Reverting back to draft: refund the slot.
      INSERT INTO public.company_quote_usage (company_id, period_start, quotes_created)
      VALUES (NEW.company_id, v_period, 0)
      ON CONFLICT (company_id, period_start)
        DO UPDATE SET quotes_created = GREATEST(company_quote_usage.quotes_created - 1, 0);
    END IF;
    RETURN NEW;
  END IF;

  -- On hard delete of a non-draft quote: refund the slot.
  -- BUT skip if the company is being deleted (cascade) - the company row
  -- is already gone, so the FK insert would fail and there's no point
  -- maintaining a usage counter for a deleted company.
  IF (TG_OP = 'DELETE') THEN
    IF OLD.status <> 'draft' THEN
      SELECT EXISTS(SELECT 1 FROM public.companies WHERE id = OLD.company_id)
        INTO v_company_exists;
      IF v_company_exists THEN
        INSERT INTO public.company_quote_usage (company_id, period_start, quotes_created)
        VALUES (OLD.company_id, v_period, 0)
        ON CONFLICT (company_id, period_start)
          DO UPDATE SET quotes_created = GREATEST(company_quote_usage.quotes_created - 1, 0);
      END IF;
    END IF;
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_ai_assist_points_status(p_company_id uuid)
 RETURNS TABLE(used integer, point_limit integer, remaining integer, is_blocked boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_effective_plan text;
  v_point_limit integer;
  v_points_used integer;
BEGIN
  SELECT public.company_effective_plan_code(p_company_id) INTO v_effective_plan;
  IF v_effective_plan IS NULL THEN
    RETURN QUERY SELECT 0, NULL, 0, true;
    RETURN;
  END IF;

  SELECT sp.ai_assist_points_limit INTO v_point_limit
  FROM subscription_plans sp
  WHERE sp.code = v_effective_plan;

  SELECT c.ai_assist_points_used INTO v_points_used
  FROM companies c
  WHERE c.id = p_company_id;

  IF v_point_limit IS NULL THEN
    RETURN QUERY SELECT 0, NULL, 0, true;
  ELSE
    RETURN QUERY SELECT v_points_used, v_point_limit, GREATEST(v_point_limit - v_points_used, 0), false;
  END IF;
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.sa_admit_run(p_conversation_id uuid, p_user_message text, p_client_request_id text)
 RETURNS TABLE(ok boolean, status text, run_id uuid, message_id uuid, error_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_conversation RECORD;
  v_flag boolean;
  v_existing_run RECORD;
  v_msg_id uuid;
  v_run_id uuid;
  v_quota RECORD;
  v_payload text;
BEGIN
  IF v_user IS NULL THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, NULL::uuid, 'unauthenticated'; RETURN;
  END IF;
  IF p_client_request_id IS NULL OR length(trim(p_client_request_id)) < 8
     OR length(p_client_request_id) > 128 THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, NULL::uuid, 'bad_request_id'; RETURN;
  END IF;
  IF p_user_message IS NULL OR length(trim(p_user_message)) = 0
     OR length(p_user_message) > 16000 THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, NULL::uuid, 'bad_message'; RETURN;
  END IF;

  SELECT * INTO v_conversation FROM public.smart_assistant_conversations c
  WHERE c.id = p_conversation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, NULL::uuid, 'conversation_not_found'; RETURN;
  END IF;
  IF v_conversation.user_id <> v_user THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, NULL::uuid, 'not_owner'; RETURN;
  END IF;

  -- DUPLICATE FIRST: a previously admitted request always resolves, even when
  -- the flag/quota would now refuse. Invariant 6.
  SELECT * INTO v_existing_run FROM public.smart_assistant_runs r
  WHERE r.conversation_id = p_conversation_id AND r.client_request_id = p_client_request_id;
  IF FOUND THEN
    -- Payload conflict: same id, different content (md5 legacy rows compatible).
    v_payload := md5(p_user_message);
    IF v_existing_run.payload_hash IS DISTINCT FROM v_payload THEN
      RETURN QUERY SELECT false, 'refused', NULL::uuid, NULL::uuid, 'request_id_conflict';
      RETURN;
    END IF;
    RETURN QUERY SELECT true, 'duplicate', v_existing_run.id, NULL::uuid, NULL::text;
    RETURN;
  END IF;

  SELECT public.smart_assistant_enabled(v_conversation.company_id) INTO v_flag;
  IF NOT COALESCE(v_flag, false) THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, NULL::uuid, 'flag_off'; RETURN;
  END IF;

  -- COMPANY-WIDE QUOTA SERIALIZATION: lock the company's flag row so two
  -- conversations cannot oversubscribe the last slot. Invariant 5.
  PERFORM 1 FROM public.assistant_feature_flags f
  WHERE f.company_id = v_conversation.company_id FOR UPDATE;

  SELECT * INTO v_quota FROM public.sa_check_turn_quota(v_conversation.company_id);
  IF v_quota.used >= v_quota.cap THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, NULL::uuid, 'quota_exceeded'; RETURN;
  END IF;

  -- Stale-run recovery with pointer validation (never touch a foreign run).
  IF v_conversation.active_run_id IS NOT NULL THEN
    UPDATE public.smart_assistant_runs r
       SET status = 'interrupted', error_code = 'stale', finished_at = now()
     WHERE r.id = v_conversation.active_run_id
       AND r.conversation_id = v_conversation.id
       AND r.company_id = v_conversation.company_id
       AND r.user_id = v_user
       AND r.status IN ('accepted','running')
       AND r.started_at < now() - interval '5 minutes';
    IF FOUND THEN
      UPDATE public.smart_assistant_conversations c
          SET active_run_id = NULL
        WHERE c.id = v_conversation.id AND c.active_run_id = v_conversation.active_run_id;
      v_conversation.active_run_id := NULL;
    END IF;
  END IF;

  IF v_conversation.active_run_id IS NOT NULL THEN
    RETURN QUERY SELECT false, 'refused', NULL::uuid, NULL::uuid, 'run_in_progress'; RETURN;
  END IF;

  INSERT INTO public.smart_assistant_messages (conversation_id, run_id, role, content)
  VALUES (p_conversation_id, NULL, 'user', p_user_message)
  RETURNING id INTO v_msg_id;

  INSERT INTO public.smart_assistant_runs (
    conversation_id, user_id, company_id, client_request_id, payload_hash, status
  ) VALUES (
    p_conversation_id, v_user, v_conversation.company_id, p_client_request_id,
    md5(p_user_message), 'accepted'
  )
  RETURNING id INTO v_run_id;

  -- Stamp the admitted message with its run for history identity.
  UPDATE public.smart_assistant_messages SET run_id = v_run_id WHERE id = v_msg_id;

  -- Durable reservation: quota survives any later transcript deletion.
  INSERT INTO public.assistant_turn_reservations (run_id, company_id, user_id)
  VALUES (v_run_id, v_conversation.company_id, v_user);

  UPDATE public.smart_assistant_conversations c
     SET active_run_id = v_run_id, last_active_at = now(), updated_at = now()
   WHERE c.id = p_conversation_id;

  RETURN QUERY SELECT true, 'accepted', v_run_id, v_msg_id, NULL::text;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_ai_scan_job(p_company_id uuid, p_user_id uuid, p_quote_id uuid, p_page_id uuid, p_quality text, p_idempotency_key text, p_image_data text, p_canvas_width integer DEFAULT 800, p_canvas_height integer DEFAULT 600)
 RETURNS TABLE(job_id uuid, status text, points_cost integer, points_remaining integer, point_limit integer, is_existing boolean, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing_id UUID;
  v_existing_status TEXT;
  v_existing_cost INT;
  v_plan_priority INT;
  v_points_cost INT;
  v_deduct_result RECORD;
  v_remaining INT;
  v_limit INT;
  v_effective_plan TEXT;
BEGIN
  -- 1. Idempotency check: return existing job without charging again
  SELECT id, status, points_cost INTO v_existing_id, v_existing_status, v_existing_cost
  FROM ai_scan_jobs
  WHERE company_id = p_company_id AND idempotency_key = p_idempotency_key;

  IF FOUND THEN
    SELECT remaining INTO v_remaining FROM public.get_ai_assist_points_status(p_company_id);
    SELECT ai_assist_points_limit INTO v_limit
    FROM subscription_plans sp
    WHERE sp.code = public.company_effective_plan_code(p_company_id);

    RETURN QUERY SELECT v_existing_id, v_existing_status, v_existing_cost,
      v_remaining, v_limit, true, NULL::TEXT;
    RETURN;
  END IF;

  -- 2. Reject if company already has an active job on this page
  PERFORM 1 FROM ai_scan_jobs
  WHERE company_id = p_company_id
    AND page_id = p_page_id
    AND status IN ('queued', 'running');

  IF FOUND THEN
    RETURN QUERY SELECT NULL::UUID, NULL::TEXT, NULL::INT, NULL::INT, NULL::INT, false,
      'ACTIVE_JOB_EXISTS'::TEXT;
    RETURN;
  END IF;

  -- 3. Determine plan priority
  v_effective_plan := public.company_effective_plan_code(p_company_id);
  v_plan_priority := CASE
    WHEN v_effective_plan = 'pro_plus' THEN 30
    WHEN v_effective_plan = 'pro' THEN 20
    WHEN v_effective_plan = 'growth' THEN 15
    WHEN v_effective_plan = 'starter' THEN 10
    ELSE 0  -- trial/free
  END;

  -- 4. Derive point cost from quality
  v_points_cost := CASE p_quality
    WHEN 'low' THEN 2
    WHEN 'medium' THEN 4
    WHEN 'high' THEN 8
    ELSE 4
  END;

  -- 5. Atomically check + deduct points
  SELECT * INTO v_deduct_result FROM public.check_and_deduct_ai_points(p_company_id, v_points_cost);

  IF NOT v_deduct_result.allowed THEN
    RETURN QUERY SELECT NULL::UUID, NULL::TEXT, NULL::INT,
      v_deduct_result.remaining, v_deduct_result.point_limit, false,
      v_deduct_result.error;
    RETURN;
  END IF;

  -- 6. Create the queued job
  INSERT INTO ai_scan_jobs (
    company_id, user_id, quote_id, page_id,
    plan_priority, quality, idempotency_key,
    status, points_cost, points_state,
    image_data, canvas_width, canvas_height,
    available_at
  ) VALUES (
    p_company_id, p_user_id, p_quote_id, p_page_id,
    v_plan_priority, p_quality, p_idempotency_key,
    'queued', v_points_cost, 'reserved',
    p_image_data, p_canvas_width, p_canvas_height,
    now()
  )
  RETURNING id, points_cost INTO v_existing_id, v_existing_cost;

  v_remaining := v_deduct_result.remaining;

  RETURN QUERY SELECT v_existing_id, 'queued'::TEXT, v_existing_cost,
    v_remaining, v_deduct_result.point_limit, false, NULL::TEXT;
  RETURN;
END;
$function$
